    private static TextView createBadgePill(Context context, String text, boolean marginEnd) {
        TextView pill = new TextView(context);
        pill.setText(text);
        pill.setTextColor(0xFFD5E5E8);
        pill.setTextSize(TypedValue.COMPLEX_UNIT_SP, 11.5f);
        pill.setTypeface(Typeface.DEFAULT_BOLD);
        int h = RexVectorIcons.dp(context, 10);
        int v = RexVectorIcons.dp(context, 5);
        pill.setPadding(h, v, h, v);
        GradientDrawable bg = new GradientDrawable();
        bg.setColor(0xFF26383C);
        bg.setCornerRadius(RexVectorIcons.dp(context, 12));
        pill.setBackground(bg);
        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.WRAP_CONTENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        if (marginEnd) lp.setMarginEnd(RexVectorIcons.dp(context, 8));
        pill.setLayoutParams(lp);
        return pill;
    }

    private static LinearLayout createSocialPill(Context context, String iconType, String label, final String url, boolean isLeft) {
        LinearLayout btn = new LinearLayout(context);
        btn.setOrientation(LinearLayout.HORIZONTAL);
        btn.setGravity(Gravity.CENTER);
        int vPad = RexVectorIcons.dp(context, 13);
        btn.setPadding(vPad, vPad, vPad, vPad);
        GradientDrawable bg = new GradientDrawable();
        bg.setColor(0xFF213135);
        bg.setCornerRadius(RexVectorIcons.dp(context, 22));
        btn.setBackground(bg);

        ImageView icon = new ImageView(context);
        int px = RexVectorIcons.dp(context, 18);
        icon.setImageDrawable(RexVectorIcons.createMenuIcon(context, iconType, 18, 0xFFB8D8E0));
        LinearLayout.LayoutParams iLp = new LinearLayout.LayoutParams(px, px);
        iLp.setMarginEnd(RexVectorIcons.dp(context, 8));
        btn.addView(icon, iLp);

        TextView tv = new TextView(context);
        tv.setText(label);
        tv.setTextColor(0xFFDCECEF);
        tv.setTextSize(TypedValue.COMPLEX_UNIT_SP, 14);
        tv.setTypeface(Typeface.DEFAULT_BOLD);
        btn.addView(tv);

        btn.setOnClickListener(v -> RexUtils.openUrl(url, false));

        LinearLayout.LayoutParams lp = new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f);
        if (isLeft) lp.setMarginEnd(RexVectorIcons.dp(context, 10));
        btn.setLayoutParams(lp);
        return btn;
    }

    private static View createCommunityRow(Context context, String iconType, String title, String subtitle, Runnable action) {
        LinearLayout card = new LinearLayout(context);
        card.setOrientation(LinearLayout.HORIZONTAL);
        card.setGravity(Gravity.CENTER_VERTICAL);
        int pad = RexVectorIcons.dp(context, 16);
        card.setPadding(pad, RexVectorIcons.dp(context, 14), pad, RexVectorIcons.dp(context, 14));
        GradientDrawable bg = new GradientDrawable();
        bg.setColor(0xFF15191C);
        bg.setCornerRadius(RexVectorIcons.dp(context, 20));
        bg.setStroke(RexVectorIcons.dp(context, 1), 0x18FFFFFF);
        card.setBackground(bg);

        FrameLayout circle = new FrameLayout(context);
        int cSize = RexVectorIcons.dp(context, 42);
        GradientDrawable cBg = new GradientDrawable();
        cBg.setShape(GradientDrawable.OVAL);
        cBg.setColor(0xFF233236);
        circle.setBackground(cBg);

        ImageView icon = new ImageView(context);
        int iSize = RexVectorIcons.dp(context, 20);
        icon.setImageDrawable(RexVectorIcons.createMenuIcon(context, iconType, 20, 0xFF88C2CE));
        FrameLayout.LayoutParams iLp = new FrameLayout.LayoutParams(iSize, iSize, Gravity.CENTER);
        circle.addView(icon, iLp);

        LinearLayout.LayoutParams cLp = new LinearLayout.LayoutParams(cSize, cSize);
        cLp.setMarginEnd(RexVectorIcons.dp(context, 14));
        card.addView(circle, cLp);

        LinearLayout texts = new LinearLayout(context);
        texts.setOrientation(LinearLayout.VERTICAL);

        TextView tView = new TextView(context);
        tView.setText(title);
        tView.setTextColor(Color.WHITE);
        tView.setTextSize(TypedValue.COMPLEX_UNIT_SP, 15.5f);
        tView.setTypeface(Typeface.DEFAULT_BOLD);
        texts.addView(tView);

        TextView sView = new TextView(context);
        sView.setText(subtitle);
        sView.setTextColor(0xFF8A949E);
        sView.setTextSize(TypedValue.COMPLEX_UNIT_SP, 12.5f);
        sView.setPadding(0, RexVectorIcons.dp(context, 2), 0, 0);
        texts.addView(sView);

        card.addView(texts, new LinearLayout.LayoutParams(0, ViewGroup.LayoutParams.WRAP_CONTENT, 1f));

        ImageView chev = new ImageView(context);
        int chPx = RexVectorIcons.dp(context, 18);
        chev.setImageDrawable(RexVectorIcons.createMenuIcon(context, "chevron_right", 18, 0xFF7B858E));
        card.addView(chev, new LinearLayout.LayoutParams(chPx, chPx));

        card.setOnClickListener(v -> {
            if (action != null) action.run();
        });

        LinearLayout.LayoutParams cardLp = new LinearLayout.LayoutParams(
                ViewGroup.LayoutParams.MATCH_PARENT, ViewGroup.LayoutParams.WRAP_CONTENT);
        cardLp.bottomMargin = RexVectorIcons.dp(context, 10);
        card.setLayoutParams(cardLp);
        return card;
    }
